WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_st_before_after'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '前后分段', 'kp-eng-st-before-after', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "前后分段工程"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "时间轴被砍成两截，前一半用效率A，后一半用效率B。列分段方程是王道。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "经典句式：“一项工程，正常需要 20 天。做了 5 天后，引进了新设备/下了雨/增加了人手，效率变成了原来的 1.5 倍……”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把完整的工程看成两截线段之和："}]}, {"type": "katexBlock", "attrs": {"content": "W_{总} = P_{旧} \\times T_{旧} + P_{新} \\times T_{新}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题目, 看到效率发生了突变] --> B[赋总量 W 和 初始效率 P旧]\nB --> C[计算突变前, 已经完成的工程量 = P旧 × T旧]\nC --> D[总量减去已完成, 得到剩下需要完成的 W余]\nD --> E[根据题目条件, 算出突变后的新效率 P新]\nE --> F[T新 = W余 ÷ P新]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 某工程计划 20 天完成。正常开工 5 天后，引进了新技术，效率提升为原来的 2 倍。问实际总共提前了几天完工？选项：A. 5  B. 7.5  C. 10  D. 12.5"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋值：因为只给了总时间 20 天，直接赋效率 P旧 = 1。则总量 W = 20。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "前半段：正常干了 5 天，完成了 1 × 5 = 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "剩后半段：剩下 W余 = 20 - 5 = 15。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "新效率：效率变为 2 倍，即 P新 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "新时间：剩下的活需要 T新 = 15 ÷ 2 = 7.5 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "回答问题：实际总天数 = 5 + 7.5 = 12.5 天。计划是 20 天，所以提前了 20 - 12.5 = 7.5 天。选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "问什么答什么：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目算出来后续时间是 7.5 天，选项里一定有 7.5（比如上面的B是正确答案，但如果问实际总天数，你选7.5就死了）。一定要用红笔圈出最后问的是“剩余时间”、“总共花费时间”还是“提前了几天”！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "培养画线段图的习惯，在线段上面写效率，下面写天数，中间画一道杠代表“突变点”。直观且绝不会出错。"}]}]}$$ AS jsonb), NULL, '前后分段的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "前后分段"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_st_before_after", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
